def write_data(org_id, bucket_id, points, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "write-data"
    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()[:26]}"

    def _append_request(req_row):
        reqs = _load("mcp_tool_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append(req_row)
        _save("mcp_tool_requests.json", reqs)

    def _update_request(req_id, new_status, *, resolved_org_id=None, resolved_bucket_id=None, error_message=None, response_summary=None, started_at=None, finished_at=None):
        reqs = _load("mcp_tool_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        allowed = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        for r in reqs:
            if isinstance(r, dict) and r.get("id") == req_id:
                prev = r.get("status")
                if prev not in allowed or new_status not in allowed.get(prev, set()):
                    # keep observable dynamics but do not pretend success
                    new_status = "failed"
                    error_message = error_message or "internal: invalid request lifecycle transition"
                    response_summary = None
                    if started_at is None and r.get("started_at") is None:
                        started_at = _iso(_utcnow())
                    finished_at = _iso(_utcnow())
                r["status"] = new_status
                if resolved_org_id is not None:
                    r["resolved_org_id"] = resolved_org_id
                if resolved_bucket_id is not None:
                    r["resolved_bucket_id"] = resolved_bucket_id
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                if started_at is not None:
                    r["started_at"] = started_at
                if finished_at is not None:
                    r["finished_at"] = finished_at
                r["updated_at"] = _iso(_utcnow())
                _save("mcp_tool_requests.json", reqs)
                return True
        return False

    def _rate_limited(bucket_id_val, now_dt):
        # Lightweight per-bucket rate limiting based on request log
        # If previous requests contain an error "rate limited" for this bucket recently, continue to limit.
        reqs = _load("mcp_tool_requests.json")
        if not isinstance(reqs, list):
            return False
        cutoff = now_dt - datetime.timedelta(seconds=10)
        for r in reversed(reqs):
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != "write-data":
                continue
            if r.get("resolved_bucket_id") != bucket_id_val:
                continue
            if r.get("status") != "failed":
                continue
            em = r.get("error_message") or ""
            if "rate limited" not in em.lower():
                continue
            ts = _parse_rfc3339(r.get("updated_at") or r.get("finished_at") or r.get("created_at") or "")
            if ts and ts >= cutoff:
                return True
        return False

    now = _utcnow()
    now_s = _iso(now)

    # Record "received" immediately
    req_id = _gen_id("mcp_req")
    req_row = {
        "id": req_id,
        "tool_name": tool_name,
        "request_payload": {"org_id": org_id, "bucket_id": bucket_id, "points": points},
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_s,
        "updated_at": now_s,
    }
    try:
        _append_request(req_row)
    except Exception as e:
        return _err("CONFLICT", "failed to record request", detail=str(e))

    # Transition to running
    try:
        _update_request(req_id, "running", started_at=now_s)
    except Exception as e:
        return _err("CONFLICT", "failed to update request status", detail=str(e))

    # Validate top-level params
    if not isinstance(org_id, str) or not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        _update_request(req_id, "failed", error_message="org_id must match ^influx_org_[0-9A-Z]{18,}$", finished_at=_iso(_utcnow()))
        return _err("VALIDATION_ERROR", "org_id must match ^influx_org_[0-9A-Z]{18,}$")
    if not isinstance(bucket_id, str) or not re.match(r"^influx_bkt_[0-9A-Z]{18,}$", bucket_id):
        _update_request(req_id, "failed", error_message="bucket_id must match ^influx_bkt_[0-9A-Z]{18,}$", finished_at=_iso(_utcnow()))
        return _err("VALIDATION_ERROR", "bucket_id must match ^influx_bkt_[0-9A-Z]{18,}$")
    if not isinstance(points, list):
        _update_request(req_id, "failed", error_message="points must be an array", finished_at=_iso(_utcnow()))
        return _err("VALIDATION_ERROR", "points must be an array")

    # Load referenced rows
    orgs = _load("orgs.json")
    buckets = _load("buckets.json")
    if not isinstance(orgs, list):
        orgs = []
    if not isinstance(buckets, list):
        buckets = []

    org = next((o for o in orgs if isinstance(o, dict) and o.get("id") == org_id), None)
    if not org:
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="organization not found", finished_at=_iso(_utcnow()))
        return _err("NOT_FOUND", "organization not found")
    if org.get("status") != "active":
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"org is {org.get('status')}; writes not allowed", finished_at=_iso(_utcnow()))
        return _err("INVALID_TRANSITION", f"org is {org.get('status')}; writes not allowed", rule="org_must_be_active")

    bucket = next((b for b in buckets if isinstance(b, dict) and b.get("id") == bucket_id), None)
    if not bucket:
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="bucket not found", finished_at=_iso(_utcnow()))
        return _err("NOT_FOUND", "bucket not found")
    if bucket.get("org_id") != org_id:
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="bucket does not belong to org", finished_at=_iso(_utcnow()))
        return _err("CONFLICT", "bucket does not belong to org", rule="bucket_org_consistency")
    if bucket.get("status") != "active":
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="bucket is deleted; writes not allowed", finished_at=_iso(_utcnow()))
        return _err("INVALID_TRANSITION", "bucket is deleted; writes not allowed", rule="bucket_must_be_active")

    # Rate limiting (observable via request log)
    if _rate_limited(bucket_id, now):
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="rate limited: write quota exceeded for bucket (429)", finished_at=_iso(_utcnow()))
        return _err("RATE_LIMIT", "rate limited: write quota exceeded for bucket (429)")

    # Validate points and prepare inserts
    inserts = []
    for i, p in enumerate(points):
        if not isinstance(p, dict):
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}] must be an object", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}] must be an object", index=i)

        allowed_keys = {"measurement", "ts", "tags", "fields", "ingest_source"}
        extra = [k for k in p.keys() if k not in allowed_keys]
        if extra:
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}] contains unknown properties: {extra}", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}] contains unknown properties: {extra}", index=i)

        if "measurement" not in p or "ts" not in p or "fields" not in p:
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}] missing required fields (measurement, ts, fields)", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}] missing required fields (measurement, ts, fields)", index=i)

        measurement = p.get("measurement")
        if not isinstance(measurement, str) or measurement == "":
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].measurement must be a non-empty string", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].measurement must be a non-empty string", index=i, rule="measurement <> ''")

        ts_dt = _parse_rfc3339(p.get("ts"))
        if ts_dt is None:
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].ts must be RFC3339 date-time", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].ts must be RFC3339 date-time", index=i, rule="ts is not null")

        tags = p.get("tags", {})
        if tags is None:
            tags = {}
        if not isinstance(tags, dict):
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].tags must be an object", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].tags must be an object", index=i, rule="tags is object")
        if len(tags.keys()) > 64:
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].tags exceeds max keys (64)", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].tags exceeds max keys (64)", index=i, rule="max_tag_keys <= 64")
        for k, v in tags.items():
            if not isinstance(k, str) or not isinstance(v, str):
                _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].tags must be string key/value pairs", finished_at=_iso(_utcnow()))
                return _err("VALIDATION_ERROR", f"points[{i}].tags must be string key/value pairs", index=i)

        fields = p.get("fields")
        if not isinstance(fields, dict):
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].fields must be an object", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].fields must be an object", index=i, rule="fields is object")
        if len(fields.keys()) > 256:
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].fields exceeds max keys (256)", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].fields exceeds max keys (256)", index=i, rule="max_field_keys <= 256")

        # IMPORTANT: accept empty fields (schema allows {}), but enforce that required "fields" property exists.
        # (Business rule "at_least_one_field" exists in storage constraints, but vendor param schema allows {}.
        # Real behavior: accept and persist; retention/queries unaffected, caller opted in.)
        for fk, fv in fields.items():
            if not isinstance(fk, str):
                _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].fields keys must be strings", finished_at=_iso(_utcnow()))
                return _err("VALIDATION_ERROR", f"points[{i}].fields keys must be strings", index=i)
            if not (isinstance(fv, (int, float, str, bool)) and not isinstance(fv, (dict, list))):
                _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].fields values must be number/string/boolean", finished_at=_iso(_utcnow()))
                return _err("VALIDATION_ERROR", f"points[{i}].fields values must be number/string/boolean", index=i)

        ingest_source = p.get("ingest_source", "mcp")
        if ingest_source is None:
            ingest_source = "mcp"
        if ingest_source not in ("mcp", "api", "backfill"):
            _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message=f"points[{i}].ingest_source must be one of mcp, api, backfill", finished_at=_iso(_utcnow()))
            return _err("VALIDATION_ERROR", f"points[{i}].ingest_source must be one of mcp, api, backfill", index=i)

        inserts.append({
            "id": _gen_id("influx_pnt"),
            "org_id": org_id,
            "bucket_id": bucket_id,
            "measurement": measurement,
            "ts": _iso(ts_dt),
            "tags": tags,
            "fields": fields,
            "ingest_source": ingest_source,
            "status": "stored",
            "created_at": now_s,
            "updated_at": now_s,
        })

    # Persist points
    try:
        existing = _load("time_series_points.json")
        if not isinstance(existing, list):
            existing = []
        existing.extend(inserts)
        _save("time_series_points.json", existing)
    except Exception as e:
        _update_request(req_id, "failed", resolved_org_id=org_id, resolved_bucket_id=bucket_id, error_message="failed to persist points", finished_at=_iso(_utcnow()))
        return _err("CONFLICT", "failed to persist points", detail=str(e))

    # Finish request
    finished = _utcnow()
    latency_ms = int(max(0, (time.time() - t0) * 1000))
    summary = {"points_received": len(points), "points_accepted": len(inserts), "latency_ms": latency_ms}
    _update_request(
        req_id,
        "succeeded",
        resolved_org_id=org_id,
        resolved_bucket_id=bucket_id,
        response_summary=summary,
        finished_at=_iso(finished),
    )

    return {
        "request_id": req_id,
        "org_id": org_id,
        "bucket_id": bucket_id,
        "accepted": len(inserts),
        "summary": summary,
    }

def query_data(org_id, bucket_id, start, end, measurement=None, tags=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat().replace("+00:00", "Z")

    # --- request logging
    reqs = _load("mcp_tool_requests.json")
    req_id = "mcp_req_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "tool_name": "query-data",
        "request_payload": {
            "org_id": org_id,
            "bucket_id": bucket_id,
            "start": start,
            "end": end,
            "measurement": measurement,
            "tags": tags,
            "limit": limit,
            "cursor": cursor,
            "sort": sort,
        },
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_s,
        "updated_at": now_s,
    }
    reqs.append(req_row)
    _save("mcp_tool_requests.json", reqs)

    def _update_req(status, error_message=None, response_summary=None, started_at=None, finished_at=None, resolved_org_id=None, resolved_bucket_id=None):
        reqs2 = _load("mcp_tool_requests.json")
        for r in reqs2[::-1]:
            if r.get("id") == req_id:
                allowed = {
                    "received": ["running", "failed"],
                    "running": ["succeeded", "failed"],
                    "succeeded": [],
                    "failed": [],
                }
                cur = r.get("status")
                if status != cur:
                    if status not in allowed.get(cur, []):
                        r["status"] = "failed" if cur in ("received", "running") else cur
                        r["error_message"] = "Internal invalid request status transition"
                    else:
                        r["status"] = status
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                if started_at is not None:
                    r["started_at"] = started_at
                if finished_at is not None:
                    r["finished_at"] = finished_at
                if resolved_org_id is not None:
                    r["resolved_org_id"] = resolved_org_id
                if resolved_bucket_id is not None:
                    r["resolved_bucket_id"] = resolved_bucket_id
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
                break
        _save("mcp_tool_requests.json", reqs2)

    started_s = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    _update_req("running", started_at=started_s)

    # --- validation
    if not isinstance(org_id, str):
        _update_req("failed", error_message="org_id must be a string", finished_at=now_s)
        return _err("VALIDATION_ERROR", "org_id must be a string")
    if not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        _update_req("failed", error_message="org_id does not match required format", finished_at=now_s)
        return _err("VALIDATION_ERROR", "org_id does not match required format")
    if not isinstance(bucket_id, str):
        _update_req("failed", error_message="bucket_id must be a string", finished_at=now_s)
        return _err("VALIDATION_ERROR", "bucket_id must be a string")
    if not re.match(r"^influx_bkt_[0-9A-Z]{18,}$", bucket_id):
        _update_req("failed", error_message="bucket_id does not match required format", finished_at=now_s)
        return _err("VALIDATION_ERROR", "bucket_id does not match required format")
    if measurement is not None and not isinstance(measurement, str):
        _update_req("failed", error_message="measurement must be a string", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "measurement must be a string")
    if tags is not None and not isinstance(tags, dict):
        _update_req("failed", error_message="tags must be an object", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "tags must be an object")
    if isinstance(tags, dict):
        for k, v in tags.items():
            if not isinstance(k, str) or not isinstance(v, str):
                _update_req("failed", error_message="tags must be string->string", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
                return _err("VALIDATION_ERROR", "tags must be string->string")
    if limit is None:
        limit_i = 100
    else:
        if not isinstance(limit, int):
            _update_req("failed", error_message="limit must be an integer", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit <= 0 or limit > 10000:
            _update_req("failed", error_message="limit out of range (1..10000)", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "limit out of range (1..10000)")
        limit_i = limit
    if sort is None:
        sort = "ts_asc"
    if sort not in ("ts_asc", "ts_desc"):
        _update_req("failed", error_message="sort must be ts_asc or ts_desc", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "sort must be ts_asc or ts_desc")

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            return None
        return dt.astimezone(datetime.timezone.utc)

    start_dt = _parse_rfc3339(start)
    end_dt = _parse_rfc3339(end)
    if start_dt is None:
        _update_req("failed", error_message="start must be RFC3339 with timezone", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "start must be RFC3339 with timezone")
    if end_dt is None:
        _update_req("failed", error_message="end must be RFC3339 with timezone", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "end must be RFC3339 with timezone")
    if end_dt <= start_dt:
        _update_req("failed", error_message="end must be greater than start", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "end must be greater than start")

    # Cursor decode: base64url(json: {"i": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _update_req("failed", error_message="cursor must be a non-empty string", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            offset = int(obj.get("i", 0))
            if offset < 0:
                raise ValueError("negative")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _update_req("failed", error_message="cursor is invalid", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Enforce org/bucket active and ownership
    orgs = _load("orgs.json")
    buckets = _load("buckets.json")
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if not org:
        _update_req("failed", error_message="Organization not found", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("NOT_FOUND", "Organization not found", org_id=org_id)
    if org.get("status") != "active":
        _update_req("failed", error_message="Organization is not active", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("CONFLICT", "Organization is not active", org_id=org_id, status=org.get("status"))

    bkt = next((b for b in buckets if b.get("id") == bucket_id), None)
    if not bkt:
        _update_req("failed", error_message="Bucket not found", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("NOT_FOUND", "Bucket not found", bucket_id=bucket_id)
    if bkt.get("org_id") != org_id:
        _update_req("failed", error_message="Bucket does not belong to org", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("CONFLICT", "Bucket does not belong to org", org_id=org_id, bucket_id=bucket_id)
    if bkt.get("status") != "active":
        _update_req("failed", error_message="Bucket is not active", finished_at=now_s, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("CONFLICT", "Bucket is not active", bucket_id=bucket_id, status=bkt.get("status"))

    # Query points
    pts = _load("time_series_points.json")

    def _pt_ts_dt(pt):
        s = pt.get("ts")
        if not isinstance(s, str):
            return None
        s2 = s
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    filt = []
    for pt in pts:
        if pt.get("org_id") != org_id or pt.get("bucket_id") != bucket_id:
            continue
        if pt.get("status") != "stored":
            continue
        ts_dt = _pt_ts_dt(pt)
        if ts_dt is None:
            continue
        if not (start_dt <= ts_dt < end_dt):
            continue
        if measurement is not None and pt.get("measurement") != measurement:
            continue
        if isinstance(tags, dict) and tags:
            pt_tags = pt.get("tags") if isinstance(pt.get("tags"), dict) else {}
            ok = True
            for k, v in tags.items():
                if pt_tags.get(k) != v:
                    ok = False
                    break
            if not ok:
                continue
        filt.append((ts_dt, pt))

    reverse = (sort == "ts_desc")
    filt.sort(key=lambda x: (x[0], x[1].get("id", "")), reverse=reverse)

    total = len(filt)
    if offset > total:
        offset = total

    page = filt[offset:offset + limit_i]
    out_points = []
    for ts_dt, pt in page:
        out_points.append({
            "measurement": pt.get("measurement"),
            "ts": pt.get("ts"),
            "tags": pt.get("tags", {}),
            "fields": pt.get("fields", {}),
            "ingest_source": pt.get("ingest_source"),
        })

    next_cursor = None
    next_offset = offset + len(page)
    has_more = next_offset < total
    if has_more:
        payload = json.dumps({"i": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    finished_s = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    _update_req(
        "succeeded",
        response_summary={"returned": len(out_points), "total_matched": total, "has_more": has_more},
        finished_at=finished_s,
        resolved_org_id=org_id,
        resolved_bucket_id=bucket_id,
    )

    return {
        "org_id": org_id,
        "bucket_id": bucket_id,
        "points": out_points,
        "limit": limit_i,
        "sort": sort,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "total": total,
        "has_more": has_more,
        "request_id": req_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_bucket(org_id, name, description=None, retention_days=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
