    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # --- request log (received)
    reqs = _load("mcp_tool_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_id = "mcp_req_" + uuid.uuid4().hex[:24]
    payload = {"org_id": org_id, "name": name}
    if description is not None:
        payload["description"] = description
    if retention_days is not None:
        payload["retention_days"] = retention_days
    reqs.append({
        "id": req_id,
        "tool_name": "create-bucket",
        "request_payload": payload,
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("mcp_tool_requests.json", reqs)

    def _set_req(status, resolved_org_id=None, resolved_bucket_id=None, error_message=None, response_summary=None, started_at=None, finished_at=None):
        reqs2 = _load("mcp_tool_requests.json")
        if not isinstance(reqs2, list):
            return
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in reversed(reqs2):
            if r.get("id") == req_id:
                cur = r.get("status")
                if status != cur and status in allowed.get(cur, []):
                    r["status"] = status
                if resolved_org_id is not None or "resolved_org_id" not in r:
                    r["resolved_org_id"] = resolved_org_id
                if resolved_bucket_id is not None or "resolved_bucket_id" not in r:
                    r["resolved_bucket_id"] = resolved_bucket_id
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                if started_at is not None:
                    r["started_at"] = started_at
                if finished_at is not None:
                    r["finished_at"] = finished_at
                r["updated_at"] = finished_at or started_at or now
                break
        _save("mcp_tool_requests.json", reqs2)

    started = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    _set_req("running", started_at=started)

    def _fail(code, message, resolved_org_id=None, **extra):
        finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        _set_req("failed", resolved_org_id=resolved_org_id, error_message=message, response_summary=extra if extra else None, finished_at=finished)
        return _err(code, message, **extra)

    if not isinstance(org_id, str) or not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        return _fail("VALIDATION_ERROR", "Malformed org_id.")
    if not isinstance(name, str) or name.strip() == "":
        return _fail("VALIDATION_ERROR", "Invalid 'name'. Must be a non-empty string.", resolved_org_id=org_id)
    if description is not None and not isinstance(description, str):
        return _fail("VALIDATION_ERROR", "Invalid 'description'. Must be a string.", resolved_org_id=org_id)
    if retention_days is not None:
        if not isinstance(retention_days, int):
            return _fail("VALIDATION_ERROR", "Invalid 'retention_days'. Must be an integer.", resolved_org_id=org_id)
        if retention_days < 0 or retention_days > 36500:
            return _fail("VALIDATION_ERROR", "Invalid 'retention_days'. Must be between 0 and 36500.", resolved_org_id=org_id)

    orgs = _load("orgs.json")
    if not isinstance(orgs, list):
        orgs = []
    org = next((o for o in orgs if o.get("id") == org_id), None)
    if org is None:
        return _fail("NOT_FOUND", "Organization not found.", resolved_org_id=org_id)
    if org.get("status") != "active":
        return _fail("INVALID_TRANSITION", "Org is not active; cannot create bucket.", resolved_org_id=org_id, org_status=org.get("status"))

    bks = _load("buckets.json")
    if not isinstance(bks, list):
        bks = []
    # unique(org_id, name)
    for b in bks:
        if b.get("org_id") == org_id and b.get("name") == name and b.get("status") != "deleted":
            return _fail("CONFLICT", "Bucket name already exists in org.", resolved_org_id=org_id, existing_bucket_id=b.get("id"))

    # retention defaulting: use org default if not provided
    if retention_days is None:
        retention_days = org.get("default_retention_days", 0)
        if not isinstance(retention_days, int):
            retention_days = 0
    # still enforce range
    if retention_days < 0 or retention_days > 36500:
        return _fail("VALIDATION_ERROR", "Invalid 'retention_days'. Must be between 0 and 36500.", resolved_org_id=org_id)

    bid = "influx_bkt_" + uuid.uuid4().hex[:26].upper()
    bucket = {
        "id": bid,
        "org_id": org_id,
        "name": name,
        "description": description,
        "retention_days": retention_days,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    bks.append(bucket)
    _save("buckets.json", bks)

    finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    latency_ms = int((time.time() - t0) * 1000)
    _set_req("succeeded", resolved_org_id=org_id, resolved_bucket_id=bid, response_summary={"bucket_id": bid, "latency_ms": latency_ms}, finished_at=finished)

    return bucket

def create_org(name, default_retention_days=None, **_extra):
    import json, os, datetime, uuid, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _gen_id(prefix):
        # Similar style to existing ids; uniqueness via random suffix
        return f"{prefix}_{uuid.uuid4().hex.upper()[:26]}"

    def _parse_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        return None

    tool_name = "create-org"
    t0 = time.time()
    now = _utcnow()
    now_s = _iso(now)

    # Create request row (received) immediately
    reqs = _load("mcp_tool_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_id = _gen_id("mcp_req")
    payload = {}
    if name is not None:
        payload["name"] = name
    if default_retention_days is not None:
        payload["default_retention_days"] = default_retention_days
    req_row = {
        "id": req_id,
        "tool_name": tool_name,
        "request_payload": payload if isinstance(payload, dict) else {},
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_s,
        "updated_at": now_s,
    }
    reqs.append(req_row)
    _save("mcp_tool_requests.json", reqs)

    def _update_req(final_status, resolved_org_id=None, error_message=None, response_summary=None):
        reqs2 = _load("mcp_tool_requests.json")
        if not isinstance(reqs2, list):
            return
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in reversed(reqs2):
            if r.get("id") == req_id:
                # Move to running if not already terminal and final isn't "received"
                if r.get("status") == "received":
                    r["status"] = "running"
                    r["started_at"] = r.get("started_at") or now_s
                # Transition to final
                cur = r.get("status")
                if final_status != cur and final_status in allowed.get(cur, []):
                    r["status"] = final_status
                elif final_status == cur:
                    pass
                else:
                    # If invalid transition, best effort mark failed from running
                    if "failed" in allowed.get(cur, []):
                        r["status"] = "failed"
                        if not r.get("error_message"):
                            r["error_message"] = "Internal invalid request status transition"
                if resolved_org_id is not None:
                    r["resolved_org_id"] = resolved_org_id
                r["resolved_bucket_id"] = None
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                finished = _iso(_utcnow())
                r["finished_at"] = finished
                r["updated_at"] = finished
                _save("mcp_tool_requests.json", reqs2)
                return

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        msg = "Validation failed: name must be a non-empty string."
        _update_req("failed", error_message=msg, response_summary={"created": False})
        return _err("VALIDATION_ERROR", msg)

    name_in = name.strip()
    if len(name_in) > 256:
        msg = "Validation failed: name is too long (max 256 characters)."
        _update_req("failed", error_message=msg, response_summary={"created": False})
        return _err("VALIDATION_ERROR", msg)

    if default_retention_days is None:
        # business: must exist in row; if not provided, derive reasonable default
        drd = 0
    else:
        drd = _parse_int(default_retention_days)
        if drd is None:
            msg = "Validation failed: default_retention_days must be an integer."
            _update_req("failed", error_message=msg, response_summary={"created": False})
            return _err("VALIDATION_ERROR", msg)
        if drd < 0 or drd > 36500:
            msg = "Validation failed: default_retention_days must be between 0 and 36500."
            _update_req("failed", error_message=msg, response_summary={"created": False})
            return _err("VALIDATION_ERROR", msg)

    # Enforce uniqueness by auto-suffixing if necessary (business rule)
    orgs = _load("orgs.json")
    if not isinstance(orgs, list):
        orgs = []
    existing_names = set()
    for o in orgs:
        if isinstance(o, dict) and isinstance(o.get("name"), str):
            existing_names.add(o["name"])

    final_name = name_in
    if final_name in existing_names:
        # Derive unique name rather than rejecting (per business rules given)
        base = final_name
        # Keep deterministic-ish but unique: suffix with "-<n>" then "-<shortid>"
        n = 2
        while True:
            candidate = f"{base} ({n})"
            if candidate not in existing_names:
                final_name = candidate
                break
            n += 1
            if n > 50:
                candidate = f"{base} ({uuid.uuid4().hex[:8]})"
                if candidate not in existing_names:
                    final_name = candidate
                    break

    # Create org row
    org_id = _gen_id("influx_org")
    created = _utcnow()
    created_s = _iso(created)
    org_row = {
        "id": org_id,
        "name": final_name,
        "status": "active",
        "default_retention_days": drd,
        "created_at": created_s,
        "updated_at": created_s,
    }
    orgs.append(org_row)
    _save("orgs.json", orgs)

    _update_req(
        "succeeded",
        resolved_org_id=org_id,
        response_summary={
            "created": True,
            "org_id": org_id,
            "name": final_name,
            "default_retention_days": drd,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    )

    return {"org": org_row}

