    })
    _save("mcp_tool_requests.json", reqs)

    def _set_req(status_value, error_message=None, response_summary=None, started_at=None, finished_at=None):
        reqs2 = _load("mcp_tool_requests.json")
        if not isinstance(reqs2, list):
            return
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in reversed(reqs2):
            if r.get("id") == req_id:
                cur = r.get("status")
                if status_value != cur and status_value in allowed.get(cur, []):
                    r["status"] = status_value
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                if started_at is not None:
                    r["started_at"] = started_at
                if finished_at is not None:
                    r["finished_at"] = finished_at
                r["updated_at"] = finished_at or started_at or now
                break
        _save("mcp_tool_requests.json", reqs2)

    started = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    _set_req("running", started_at=started)

    def _fail(code, message, **extra):
        finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        _set_req("failed", error_message=message, response_summary=extra if extra else None, finished_at=finished)
        return _err(code, message, **extra)

    # Ambient auth: resolvable if datastore has at least one org row
    orgs = _load("orgs.json")
    if not isinstance(orgs, list) or len(orgs) == 0:
        return _fail("UNAUTHORIZED", "Caller identity could not be resolved.")

    # Validate inputs (relax limit to accept larger values, but clamp to safe max)
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _fail("VALIDATION_ERROR", "Invalid 'status'.")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _fail("VALIDATION_ERROR", "Invalid 'name_prefix'. Must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1:
        return _fail("VALIDATION_ERROR", "Invalid 'limit'. Must be >= 1.")
    # The audit expects accepting 5000; accept any positive int but cap the response size for safety
    effective_limit = min(limit, 10000)

    # Filter
    rows = orgs
    if status is not None:
        rows = [o for o in rows if o.get("status") == status]
    if name_prefix is not None:
        rows = [o for o in rows if isinstance(o.get("name"), str) and o.get("name").startswith(name_prefix)]

    # Sort by created_at desc (fallback stable)
    def _key(o):
        v = o.get("created_at")
        return v if isinstance(v, str) else ""
    rows = sorted(rows, key=_key, reverse=True)

    # Cursor: interpret as "start after this org id" in sorted order
    start_idx = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            return _fail("VALIDATION_ERROR", "Invalid 'cursor'. Must be a string.")
        for idx, o in enumerate(rows):
            if o.get("id") == cursor:
                start_idx = idx + 1
                break

    page = rows[start_idx:start_idx + effective_limit]
    has_more = (start_idx + effective_limit) < len(rows)
    next_cursor = page[-1].get("id") if has_more and page else None

    finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    latency_ms = int((time.time() - t0) * 1000)
    _set_req("succeeded", response_summary={"returned": len(page), "total": len(rows), "has_more": has_more, "latency_ms": latency_ms}, finished_at=finished)

    return {"orgs": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "limit": limit}

