    def _set_req(status_value, resolved_org_id=None, error_message=None, response_summary=None, started_at=None, finished_at=None):
        reqs2 = _load("mcp_tool_requests.json")
        if not isinstance(reqs2, list):
            return
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        for r in reversed(reqs2):
            if r.get("id") == req_id:
                cur = r.get("status")
                if status_value != cur and status_value in allowed.get(cur, []):
                    r["status"] = status_value
                r["resolved_org_id"] = resolved_org_id
                if error_message is not None:
                    r["error_message"] = error_message
                if response_summary is not None:
                    r["response_summary"] = response_summary
                if started_at is not None:
                    r["started_at"] = started_at
                if finished_at is not None:
                    r["finished_at"] = finished_at
                r["updated_at"] = finished_at or started_at or now
                break
        _save("mcp_tool_requests.json", reqs2)

    started = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    _set_req("running", started_at=started)

    def _fail(code, message, resolved_org_id=None, **extra):
        finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        _set_req("failed", resolved_org_id=resolved_org_id, error_message=message, response_summary=extra if extra else None, finished_at=finished)
        return _err(code, message, **extra)

    if not isinstance(org_id, str) or not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        return _fail("VALIDATION_ERROR", "Malformed org_id.")
    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        return _fail("VALIDATION_ERROR", "Invalid 'name'. Must be a non-empty string.", resolved_org_id=org_id)
    if default_retention_days is not None:
        if not isinstance(default_retention_days, int):
            return _fail("VALIDATION_ERROR", "Invalid 'default_retention_days'. Must be an integer.", resolved_org_id=org_id)
        if default_retention_days < 0 or default_retention_days > 36500:
            return _fail("VALIDATION_ERROR", "Invalid 'default_retention_days'. Must be between 0 and 36500.", resolved_org_id=org_id)
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _fail("VALIDATION_ERROR", "Invalid 'status'.", resolved_org_id=org_id)

    orgs = _load("orgs.json")
    if not isinstance(orgs, list):
        orgs = []
    idx = None
    for i, o in enumerate(orgs):
        if o.get("id") == org_id:
            idx = i
            break
    if idx is None:
        return _fail("NOT_FOUND", "Organization not found.", resolved_org_id=org_id)

    org = orgs[idx]
    cur_status = org.get("status")

    # Determine changes
    changes = {}
    if name is not None and name != org.get("name"):
        # unique(name)
        for other in orgs:
            if other.get("id") != org_id and other.get("name") == name and other.get("status") != "deleted":
                return _fail("CONFLICT", "Organization name already exists.", resolved_org_id=org_id, existing_org_id=other.get("id"))
        changes["name"] = name
    if default_retention_days is not None and default_retention_days != org.get("default_retention_days"):
        changes["default_retention_days"] = default_retention_days

    if status is not None and status != cur_status:
        transitions = {"active": ["suspended", "deleted"], "suspended": ["active", "deleted"], "deleted": []}
        if status not in transitions.get(cur_status, []):
            return _fail("INVALID_TRANSITION", f"Illegal status transition: {cur_status} -> {status}.", resolved_org_id=org_id, from_status=cur_status, to_status=status)
        changes["status"] = status

    if not changes:
        # idempotent: return existing record, mark succeeded (not a validation error)
        finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        latency_ms = int((time.time() - t0) * 1000)
        _set_req("succeeded", resolved_org_id=org_id, response_summary={"updated": False, "latency_ms": latency_ms}, finished_at=finished)
        return org

    # Apply and persist
    for k, v in changes.items():
        org[k] = v
    org["updated_at"] = now
    orgs[idx] = org
    _save("orgs.json", orgs)

    finished = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    latency_ms = int((time.time() - t0) * 1000)
    _set_req("succeeded", resolved_org_id=org_id, response_summary={"updated": True, "fields": sorted(changes.keys()), "latency_ms": latency_ms}, finished_at=finished)

    return org

def list_buckets(org_id, status=None, name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate org_id
    if not isinstance(org_id, str) or not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        # log failed
        reqs = _load("mcp_tool_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        rid = "mcp_req_" + uuid.uuid4().hex
        reqs.append({
            "id": rid,
            "tool_name": "query-data",
            "request_payload": {"org_id": org_id, "status": status, "name_prefix": name_prefix, "limit": limit, "cursor": cursor},
            "resolved_org_id": None,
            "resolved_bucket_id": None,
            "status": "failed",
            "error_message": "Malformed org_id.",
            "response_summary": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("mcp_tool_requests.json", reqs)
        return _err("VALIDATION_ERROR", "Malformed org_id.")

    if status is not None and status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid 'status'.")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "Invalid 'name_prefix'. Must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be between 1 and 200.")

    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or "start_after" not in payload:
                raise ValueError("bad cursor")
            start_after = payload["start_after"]
            if start_after is not None and not isinstance(start_after, str):
                raise ValueError("bad cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Malformed cursor.")

    # Request log (use query-data tool_name)
    reqs = _load("mcp_tool_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    rid = "mcp_req_" + uuid.uuid4().hex
    req_row = {
        "id": rid,
        "tool_name": "query-data",
        "request_payload": {"org_id": org_id, "status": status, "name_prefix": name_prefix, "limit": limit, "cursor": cursor},
        "resolved_org_id": org_id,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("mcp_tool_requests.json", reqs)

    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now
    _save("mcp_tool_requests.json", reqs)

    orgs = _load("orgs.json")
    if not isinstance(orgs, list):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = "failed"
        req_row["error_message"] = "Caller identity could not be resolved."
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("mcp_tool_requests.json", reqs)
        return _err("UNAUTHORIZED", "Caller identity could not be resolved.")

    org = None
    for o in orgs:
        if isinstance(o, dict) and o.get("id") == org_id:
            org = o
            break
    if org is None:
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = "failed"
        req_row["error_message"] = "Organization not found."
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("mcp_tool_requests.json", reqs)
        return _err("NOT_FOUND", "Organization not found.")

    buckets = _load("buckets.json")
    if not isinstance(buckets, list):
        buckets = []

    rows = [b for b in buckets if isinstance(b, dict) and b.get("org_id") == org_id]
    if status is not None:
        rows = [b for b in rows if b.get("status") == status]
    if name_prefix is not None:
        rows = [b for b in rows if isinstance(b.get("name"), str) and b["name"].startswith(name_prefix)]

    def _dt_key(b):
        v = b.get("created_at")
        if isinstance(v, str):
            return v
        return ""
    rows.sort(key=_dt_key, reverse=True)

    if start_after is not None:
        idx = None
        for i, b in enumerate(rows):
            if b.get("id") == start_after:
                idx = i
                break
        if idx is not None:
            rows = rows[idx + 1:]

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and len(page) > 0:
        payload = {"v": 1, "start_after": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "succeeded"
    req_row["finished_at"] = finished
    req_row["updated_at"] = finished
    req_row["response_summary"] = {"returned": len(page), "has_more": has_more, "org_id": org_id}
    _save("mcp_tool_requests.json", reqs)

    return {
        "buckets": page,
        "total": len(rows) if start_after is None else None,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_bucket(org_id, bucket_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Prepare request logging (must happen for every call)
    reqs = _load("mcp_tool_requests.json")
    def _new_req_id():
        # 18+ chars required in other ids; requests have no explicit pattern, but keep consistent.
        import secrets
        return "mcp_req_" + secrets.token_hex(12).upper()
    req_row = {
        "id": _new_req_id(),
        "tool_name": "query-data",  # schema enum does not include get-bucket; log under nearest read operation
        "request_payload": {"org_id": org_id, "bucket_id": bucket_id},
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("mcp_tool_requests.json", reqs)

    def _finalize(status, error_message=None, response_summary=None, resolved_org_id=None, resolved_bucket_id=None):
        # reload to avoid overwriting concurrent writes (best-effort for file store)
        all_reqs = _load("mcp_tool_requests.json")
        for r in reversed(all_reqs):
            if r.get("id") == req_row["id"]:
                # transition: received -> running -> succeeded/failed (or received->failed)
                r["status"] = "running" if status in ("succeeded", "failed") else status
                r["started_at"] = r.get("started_at") or datetime.datetime.now(datetime.timezone.utc).isoformat()
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                if status in ("succeeded", "failed"):
                    r["status"] = status
                    r["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                r["error_message"] = error_message
                r["response_summary"] = response_summary
                r["resolved_org_id"] = resolved_org_id
                r["resolved_bucket_id"] = resolved_bucket_id
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                break
        _save("mcp_tool_requests.json", all_reqs)

    # Validate inputs
    if not isinstance(org_id, str) or not re.match(r"^influx_org_[0-9A-Z]{18,}$", org_id):
        _finalize("failed", error_message="org_id is malformed", response_summary={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "org_id is malformed", field="org_id")

    if not isinstance(bucket_id, str) or not re.match(r"^influx_bkt_[0-9A-Z]{18,}$", bucket_id):
        _finalize("failed", error_message="bucket_id is malformed", response_summary={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "bucket_id is malformed", field="bucket_id")

    # Run
    try:
        orgs = _load("orgs.json")
        buckets = _load("buckets.json")

        org = next((o for o in orgs if o.get("id") == org_id), None)
        if org is None:
            _finalize("failed", error_message="organization not found", response_summary={"error_code": "NOT_FOUND"}, resolved_org_id=org_id)
            return _err("NOT_FOUND", "organization not found", org_id=org_id)

        bkt = next((b for b in buckets if b.get("id") == bucket_id and b.get("org_id") == org_id), None)
        if bkt is None:
            _finalize(
                "failed",
                error_message="bucket not found in org",
                response_summary={"error_code": "NOT_FOUND"},
                resolved_org_id=org_id,
                resolved_bucket_id=bucket_id,
            )
            return _err("NOT_FOUND", "bucket not found in org", org_id=org_id, bucket_id=bucket_id)

        # Per service rules: writes/queries fail against deleted entities; for get-bucket, treat deleted as not found.
        if org.get("status") != "active":
            _finalize(
                "failed",
                error_message=f"organization is not active (status={org.get('status')})",
                response_summary={"error_code": "NOT_FOUND"},
                resolved_org_id=org_id,
                resolved_bucket_id=bucket_id,
            )
            return _err("NOT_FOUND", "bucket not found in org", org_id=org_id, bucket_id=bucket_id)

        if bkt.get("status") != "active":
            _finalize(
                "failed",
                error_message=f"bucket is not active (status={bkt.get('status')})",
                response_summary={"error_code": "NOT_FOUND"},
                resolved_org_id=org_id,
                resolved_bucket_id=bucket_id,
            )
            return _err("NOT_FOUND", "bucket not found in org", org_id=org_id, bucket_id=bucket_id)

        _finalize(
            "succeeded",
            response_summary={"bucket_id": bucket_id, "org_id": org_id, "latency_ms": int((time.time() - t0) * 1000)},
            resolved_org_id=org_id,
            resolved_bucket_id=bucket_id,
        )
        return {"bucket": bkt}
    except Exception as e:
        # Unexpected server failure: record as failed but do not mask programming errors with fake "service" errors
        _finalize("failed", error_message=f"internal error: {e}", response_summary={"error_code": "FAILED"})
        return _err("CONFLICT", "internal error")

def update_bucket(org_id, bucket_id, name=None, description=None, retention_days=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0387000" if __import__("os").path.isdir("./environment_mix/0387000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Create request log row (received)
    reqs = _load("mcp_tool_requests.json")
    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))
    req_id = _gen_id("mcp_req_")
    payload = {"org_id": org_id, "bucket_id": bucket_id}
    if name is not None: payload["name"] = name
    if description is not None: payload["description"] = description
    if retention_days is not None: payload["retention_days"] = retention_days
    if status is not None: payload["status"] = status

    req_row = {
        "id": req_id,
        "tool_name": "update-bucket",
        "request_payload": payload,
        "resolved_org_id": None,
        "resolved_bucket_id": None,
        "status": "received",
        "error_message": None,
        "response_summary": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("mcp_tool_requests.json", reqs)

    def _set_status(new_status, error_message=None, response_summary=None, resolved_org_id=None, resolved_bucket_id=None):
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _reqs = _load("mcp_tool_requests.json")
        for r in reversed(_reqs):
            if r.get("id") == req_id:
                if r.get("status") == "received" and new_status in ("running", "failed"):
                    r["status"] = "running" if new_status == "running" else "failed"
                    r["started_at"] = r.get("started_at") or ts
                    r["updated_at"] = ts
                    if new_status == "failed":
                        r["finished_at"] = ts
                if new_status in ("succeeded", "failed"):
                    if r.get("started_at") is None:
                        r["started_at"] = ts
                    r["finished_at"] = ts
                r["status"] = new_status
                r["error_message"] = error_message
                r["response_summary"] = response_summary
                r["resolved_org_id"] = resolved_org_id
                r["resolved_bucket_id"] = resolved_bucket_id
                r["updated_at"] = ts
                break
        _save("mcp_tool_requests.json", _reqs)

    # Validate required IDs
    org_pat = re.compile(r"^influx_org_[0-9A-Z]{18,}$")
    bkt_pat = re.compile(r"^influx_bkt_[0-9A-Z]{18,}$")
    if not isinstance(org_id, str) or not org_pat.match(org_id):
        _set_status("failed", error_message="Malformed org_id.", response_summary={"error": "validation"}, resolved_org_id=None, resolved_bucket_id=None)
        return _err("VALIDATION_ERROR", "Malformed org_id.", field="org_id")
    if not isinstance(bucket_id, str) or not bkt_pat.match(bucket_id):
        _set_status("failed", error_message="Malformed bucket_id.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=None)
        return _err("VALIDATION_ERROR", "Malformed bucket_id.", field="bucket_id")

    # Validate optional fields types/ranges/enums
    if name is not None and not isinstance(name, str):
        _set_status("failed", error_message="Invalid name type.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "Invalid name type.", field="name")
    if description is not None and not isinstance(description, str):
        _set_status("failed", error_message="Invalid description type.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("VALIDATION_ERROR", "Invalid description type.", field="description")
    if retention_days is not None:
        if not isinstance(retention_days, int):
            _set_status("failed", error_message="Invalid retention_days type.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "Invalid retention_days type.", field="retention_days")
        if retention_days < 0 or retention_days > 36500:
            _set_status("failed", error_message="retention_days out of range.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "retention_days out of range (0..36500).", field="retention_days")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _set_status("failed", error_message="Invalid status value.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status", allowed=["active", "deleted"])

    # Start running
    _set_status("running", resolved_org_id=org_id, resolved_bucket_id=bucket_id)

    orgs = _load("orgs.json")
    buckets = _load("buckets.json")

    org = next((o for o in orgs if o.get("id") == org_id), None)
    if org is None:
        _set_status("failed", error_message="Organization not found.", response_summary={"error": "not_found"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("NOT_FOUND", "Organization not found.", org_id=org_id)

    idx = None
    for i, b in enumerate(buckets):
        if b.get("id") == bucket_id and b.get("org_id") == org_id:
            idx = i
            break
    if idx is None:
        _set_status("failed", error_message="Bucket not found in org.", response_summary={"error": "not_found"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("NOT_FOUND", "Bucket not found in org.", org_id=org_id, bucket_id=bucket_id)

    bucket = buckets[idx]
    original = dict(bucket)

    # Enforce name uniqueness within org if updating
    if name is not None:
        nm = name.strip()
        if nm == "":
            _set_status("failed", error_message="Bucket name cannot be empty.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "Bucket name cannot be empty.", field="name")
        for b in buckets:
            if b.get("org_id") == org_id and b.get("id") != bucket_id and b.get("name") == nm:
                _set_status("failed", error_message="Bucket name already exists in org.", response_summary={"error": "conflict"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
                return _err("CONFLICT", "Bucket name already exists in org.", org_id=org_id, name=nm)
        bucket["name"] = nm

    if description is not None:
        bucket["description"] = description

    if retention_days is not None:
        bucket["retention_days"] = retention_days

    # Lifecycle transition validation
    if status is not None:
        cur = bucket.get("status")
        if cur not in ("active", "deleted"):
            _set_status("failed", error_message="Bucket has invalid stored status.", response_summary={"error": "validation"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
            return _err("VALIDATION_ERROR", "Bucket has invalid stored status.", field="status")
        allowed = {"active": ["deleted"], "deleted": []}
        if status != cur:
            if status not in allowed.get(cur, []):
                _set_status("failed", error_message="Illegal status transition.", response_summary={"error": "invalid_transition", "from": cur, "to": status}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)
            bucket["status"] = status

    # Require at least one effective change
    changed = any(bucket.get(k) != original.get(k) for k in set(bucket.keys()).union(original.keys()))
    if not changed:
        _set_status("failed", error_message="No changes applied (bucket already matches requested state).", response_summary={"error": "not_found_or_noop"}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
        return _err("NOT_FOUND", "No changes applied (bucket already matches requested state).", org_id=org_id, bucket_id=bucket_id)

    bucket["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    buckets[idx] = bucket
    _save("buckets.json", buckets)

    latency_ms = int((time.time() - t0) * 1000)
    _set_status("succeeded", response_summary={"latency_ms": latency_ms, "bucket_id": bucket_id, "changed_fields": [k for k in ("name", "description", "retention_days", "status") if original.get(k) != bucket.get(k)]}, resolved_org_id=org_id, resolved_bucket_id=bucket_id)
    return {"bucket": bucket}
